import os

# Get URL from user
def get_url():
    return input("Enter URL to scan: ")

# Perform a security scan on a URL
def scan(url):
    results = os.popen(f"curl -s --head {url}").read()

    return results

def main():
    url = get_url()

    results = scan(url)

    print(results)

if __name__ == '__main__':
    main()

