import java.util.*;

class Geometry {
  public static void main(String[] args) {
    String shape = args[0];
    double area = Double.parseDouble(args[1]);

    switch(shape) {
      case "circle":
        double radius = Math.sqrt(area / Math.PI);
        System.out.println("The radius of the circle is " + radius + ".");
        break;
      case "square":
        double side = Math.sqrt(area);
        System.out.println("The side length of the square is " + side + ".");
        break;
      case "triangle":
        double base = Math.sqrt(area * 2 * (area - side));
        System.out.println("The base length of the triangle is " + base + ".");
    }
  }
}

