from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/guests', methods=['GET'])
def viewGuests():
    guests = request.get_json()
    message = "<p>Our guests include:</p>"

    for guest in guests:
        name = guest['name']
        email = guest['email']

        message += f"<p>{name} - {email}</p>"

    return message

if __name__ == '__main__':
    app.run()

